import * as THREE from 'three';
import { galleryWalkingPoints } from './exhibitionArchitecture.js';

export const EXHIBITION_TURN_RATE = 130 * Math.PI / 180;

export function exhibitionTurnDuration(turn, minimum = .45) {
  // Quintic easing reaches 1.875 times its mean speed. A half turn needs
  // proportionally more time than a small adjustment at the same location.
  return Math.max(minimum, Math.abs(turn) * 1.875 / EXHIBITION_TURN_RATE);
}

export function exhibitionDeparture(origin, pitch, readingOrigin = origin) {
  const target = readingOrigin.clone(); target.y = 1.72;
  return { elapsed:0, origin:origin.clone(), target, pitch, duration:Math.min(1.4, Math.max(.65, origin.distanceTo(target)*.4)) };
}

export function exhibitionDeparturePose(departure, elapsed) {
  const progress=THREE.MathUtils.smootherstep(elapsed/departure.duration,0,1);
  return {position:departure.origin.clone().lerp(departure.target,progress),pitch:THREE.MathUtils.lerp(departure.pitch,0,progress)};
}

export function exhibitionApproachProgress(current, proposed, turn, slope, dt) {
  const start = exhibitionApproachAngle(0, turn, slope, current);
  const limit = EXHIBITION_TURN_RATE * dt;
  if (Math.abs(exhibitionApproachAngle(0, turn, slope, proposed) - start) <= limit) return proposed;
  let low = current, high = proposed;
  for (let i=0;i<24;i++) {
    const middle = (low+high)/2;
    if (Math.abs(exhibitionApproachAngle(0, turn, slope, middle)-start) > limit) high=middle;
    else low=middle;
  }
  return low;
}

export function exhibitionGalleryPath(plan, origin, eye) {
  const points = galleryWalkingPoints(plan, origin, eye).map(point => new THREE.Vector3(...point));
  let previous = new THREE.Vector3(origin.x, 1.72, origin.z);
  return roundWalkingCorners(origin, points, .65).filter(point => {
    if (previous.distanceToSquared(point) < 1e-12) return false;
    previous = point;
    return true;
  });
}

export function exhibitionWalkingLook(eye, target) {
  const look = target.clone();
  // A low cabinet is read after arrival. Keep the horizon level throughout
  // the approach, including a half turn into the cabinet's front position.
  if (Math.abs(eye.y - 1.72) > .2) look.y = 1.72;
  return look;
}

export function exhibitionArrival(origin, yaw, pitch, eye, target) {
  const pose = exhibitionLookPose(eye, target);
  const turn = Math.atan2(Math.sin(pose.yaw - yaw), Math.cos(pose.yaw - yaw));
  const alignDuration = Math.abs(turn) > .0001 ? exhibitionTurnDuration(turn, 0) : 0;
  const leanDuration = Math.abs(eye.y - origin.y) > .5 ? 1.4 : .45;
  return { elapsed: 0, origin: origin.clone(), yaw, pitch, pose, turn, alignDuration, leanDuration, duration: alignDuration + leanDuration };
}

export function exhibitionArrivalPose(arrival, elapsed) {
  const align = arrival.alignDuration ? THREE.MathUtils.smootherstep(elapsed / arrival.alignDuration, 0, 1) : 1;
  const lean = THREE.MathUtils.smootherstep((elapsed - arrival.alignDuration) / arrival.leanDuration, 0, 1);
  const position = arrival.origin.clone();
  position.y = THREE.MathUtils.lerp(arrival.origin.y, arrival.pose.position.y, lean);
  return { position, yaw: arrival.yaw + arrival.turn * align, pitch: THREE.MathUtils.lerp(arrival.pitch, arrival.pose.pitch, lean) };
}

// Match the turn already in progress at the approach boundary, then finish
// with zero angular velocity. A fresh ease-in here briefly stops the gaze.
export function exhibitionApproachAngle(start, turn, slope, progress) {
  const t = THREE.MathUtils.clamp(progress, 0, 1);
  // Momentum from a previous corner must not turn away from the destination.
  // The monotone Hermite bound also prevents overshooting a small final turn.
  const tangent = turn ? Math.sign(turn) * THREE.MathUtils.clamp(slope * Math.sign(turn), 0, 3 * Math.abs(turn)) : 0;
  return start + turn * t * t * (3 - 2 * t) + tangent * t * (1 - t) * (1 - t);
}

export function exhibitionApproachGaze(approach, position, target, progress) {
  const direction=target.clone().sub(position);
  const bearing=Math.atan2(-direction.x,-direction.z);
  // Keep the landmark on the same angular branch as the initial view of it.
  // Its bearing changes naturally as the visitor approaches its front.
  const unwrapped=approach.bearing+Math.atan2(Math.sin(bearing-approach.bearing),Math.cos(bearing-approach.bearing));
  const pitch=Math.atan2(direction.y,Math.hypot(direction.x,direction.z));
  return {
    yaw:exhibitionApproachAngle(approach.yaw,unwrapped-approach.yaw,approach.yawSlope,progress),
    pitch:exhibitionApproachAngle(approach.pitch,pitch-approach.pitch,approach.pitchSlope,progress),
  };
}

export function exhibitionApproach(origin, yaw, pitch, target, distance, yawSlope=0, pitchSlope=0) {
  const direction=target.clone().sub(origin),bearing=Math.atan2(-direction.x,-direction.z);
  return {distance,yaw,pitch,bearing:yaw+Math.atan2(Math.sin(bearing-yaw),Math.cos(bearing-yaw)),yawSlope,pitchSlope};
}

export function exhibitionPathPosition(origin, path, distance) {
  let previous=origin;
  for(const point of path){
    const length=previous.distanceTo(point);
    if(distance<=length)return previous.clone().lerp(point,length?distance/length:0);
    distance-=length;previous=point;
  }
  return previous.clone();
}

export function exhibitionGazeProgress(current, proposed, poseAt, yaw, dt) {
  const limit=EXHIBITION_TURN_RATE*dt;
  if(Math.abs(poseAt(proposed).yaw-yaw)<=limit)return proposed;
  let low=current,high=proposed;
  for(let i=0;i<20;i++){
    const middle=(low+high)/2;
    if(Math.abs(poseAt(middle).yaw-yaw)<=limit)low=middle;else high=middle;
  }
  return low;
}

export function exhibitionWalkingPath(rooms, origin, eye, close = false) {
  const path = [];
  const doors = rooms.filter(room => !close && room.front < Math.max(origin.z, eye.z) && room.front > Math.min(origin.z, eye.z));
  const sign = eye.z < origin.z ? 1 : -1;
  if (sign < 0) doors.reverse();
  if (doors.length) {
    for (const door of doors) path.push(new THREE.Vector3(door.doorX, 1.72, door.front + sign * 1.3), new THREE.Vector3(door.doorX, 1.72, door.front - sign * 1.3));
  } else if (!close && Math.hypot(origin.x - eye.x, origin.z - eye.z) > 5) {
    path.push(new THREE.Vector3(0, 1.72, origin.z), new THREE.Vector3(0, 1.72, eye.z));
  }
  path.push(new THREE.Vector3(eye.x, 1.72, eye.z));
  return roundWalkingCorners(origin, path);
}

// Round only the floor path. The short curves remain inside each doorway's
// approach clearance, while preserving the exact final standing position.
export function roundWalkingCorners(origin, points, radius = .8) {
  const result = [];
  let previous = origin.clone(); previous.y = 1.72;
  points.forEach((corner, index) => {
    const next = points[index + 1];
    if (!next) { result.push(corner.clone()); return; }
    const incoming = corner.clone().sub(previous), outgoing = next.clone().sub(corner);
    const reach = Math.min(radius, incoming.length() * .35, outgoing.length() * .35);
    if (reach < .02 || incoming.clone().normalize().dot(outgoing.clone().normalize()) > .995) result.push(corner.clone());
    else {
      const a = corner.clone().addScaledVector(incoming.normalize(), -reach);
      const b = corner.clone().addScaledVector(outgoing.normalize(), reach);
      result.push(a);
      for (let i = 1; i <= 8; i++) {
        const t = i / 8;
        result.push(a.clone().multiplyScalar((1-t)*(1-t)).addScaledVector(corner, 2*(1-t)*t).addScaledVector(b, t*t));
      }
    }
    previous = corner;
  });
  result.forEach(point => { point.y = 1.72; });
  return result;
}

// Follow a point ahead on the actual walking route. Doorway waypoints never
// alternate the gaze between the door and a distant exhibit.
export function exhibitionTravelGaze(position, path, destinationLook, lookAhead = 3.2) {
  let start = position, remaining = lookAhead;
  let ahead = path.at(-1)?.clone() || destinationLook.clone();
  let total = 0;
  for (const point of path) { total += start.distanceTo(point); start = point; }
  start = position;
  for (const point of path) {
    const length = start.distanceTo(point);
    if (length >= remaining) { ahead = start.clone().lerp(point, length ? remaining / length : 0); break; }
    remaining -= length; start = point;
  }
  const weight = THREE.MathUtils.smoothstep(total, 0, 5.2);
  const routeDirection = ahead.clone().sub(position);
  // Walking follows the floor. A raised endpoint must never pull the gaze up
  // before it settles on a low exhibit.
  routeDirection.y = 0; routeDirection.normalize();
  const finalDirection = destinationLook.clone().sub(path.at(-1) || position).normalize();
  const routeYaw = Math.atan2(-routeDirection.x, -routeDirection.z);
  const finalYaw = Math.atan2(-finalDirection.x, -finalDirection.z);
  const turn = Math.atan2(Math.sin(finalYaw - routeYaw), Math.cos(finalYaw - routeYaw));
  const yaw = routeYaw + turn * (1 - weight);
  const pitch = Math.atan2(finalDirection.y, Math.hypot(finalDirection.x, finalDirection.z)) * (1 - weight);
  // Blend angles, so a return towards the entrance also has a continuous turn.
  // Opposing direction vectors would otherwise cancel halfway and flip at once.
  return position.clone().add(new THREE.Vector3(-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch)));
}


export function exhibitionVisitorPose(origin, target, rotation = 0, fov=48, aspect=1.6) {
  const orientation=new THREE.Quaternion().setFromEuler(new THREE.Euler(-.68,rotation,0,'YXZ'));
  return exhibitionSurfacePose({point:target,normal:new THREE.Vector3(0,0,1).applyQuaternion(orientation),up:new THREE.Vector3(0,1,0).applyQuaternion(orientation),width:1.97*.68,height:1.64*.68},rotation,fov,aspect,.43);
}

export function exhibitionLookPose(origin, target) {
  const position = origin.clone();
  const delta = target.clone().sub(position);
  return { position, yaw: Math.atan2(-delta.x, -delta.z), pitch: Math.atan2(delta.y, Math.hypot(delta.x, delta.z)) };
}


export function exhibitionSurfacePose(surface, rotation, fov = 48, aspect = 1.6, available = .68) {
  const half=Math.tan(fov*Math.PI/360);
  const distance=Math.max(surface.height/(2*half*.82),surface.width/(2*half*aspect*available));
  const position=surface.point.clone().addScaledVector(surface.normal,distance);
  const pitch=-Math.asin(THREE.MathUtils.clamp(surface.normal.y,-1,1));
  return {position,yaw:rotation,pitch};
}
