// Keep upright reading surfaces parallel to the image plane. Lens shift
// provides headroom without tilting the camera towards the top of the text.
export function exhibitionFramedView(view) {
  const eye=[...view.eye],target=[...view.target];
  const distance=Math.hypot(target[0]-eye[0],target[2]-eye[2]);
  const lift=view.flat&&distance>0?(target[1]-eye[1])/distance:0;
  if(view.flat)target[1]=eye[1];
  return {eye,target,lift};
}

export function exhibitionLensShift(lift, fov) {
  return -lift/(2*Math.tan(fov*Math.PI/360));
}
